using System.Net.Http.Headers;
using System.Text.Json;
namespace Keynote.Online;
public sealed class OpennanProvider(HttpClient http) : ISongToMidiProvider {
 static readonly string[] Extensions={".mp3",".wav",".m4a",".ogg",".flac",".mp4",".mov",".webm"};
 static string SafeId(string id) { if(string.IsNullOrWhiteSpace(id) || id.Length>128 || !id.All(c=>char.IsAsciiLetterOrDigit(c)||c is '-' or '_'))throw new InvalidDataException("Invalid transcription job ID."); return id; }
 static void CheckYoutube(string? value) { if(!Uri.TryCreate(value,UriKind.Absolute,out var uri) || uri.Scheme!=Uri.UriSchemeHttps || !uri.IsDefaultPort || !string.IsNullOrEmpty(uri.UserInfo) || !(uri.Host.Equals("youtube.com",StringComparison.OrdinalIgnoreCase)||uri.Host.Equals("www.youtube.com",StringComparison.OrdinalIgnoreCase)||uri.Host.Equals("m.youtube.com",StringComparison.OrdinalIgnoreCase)||uri.Host.Equals("youtu.be",StringComparison.OrdinalIgnoreCase)))throw new ArgumentException("Only HTTPS YouTube links are supported."); }
 static async Task<JsonDocument> ReadJson(HttpResponseMessage response,CancellationToken token) { if(!response.IsSuccessStatusCode) { var retry=response.Headers.RetryAfter?.ToString(); throw new HttpRequestException($"Opennan returned {(int)response.StatusCode} {response.ReasonPhrase}."+(retry!=null?$" Retry after {retry}.":"")); } if(response.Content.Headers.ContentLength>1024*1024)throw new InvalidDataException("Provider response is too large."); await using var source=await response.Content.ReadAsStreamAsync(token); using var buffer=new MemoryStream(); var chunk=new byte[8192]; int n; while((n=await source.ReadAsync(chunk,token))>0) { if(buffer.Length+n>1024*1024)throw new InvalidDataException("Provider response is too large."); buffer.Write(chunk,0,n); } buffer.Position=0; return await JsonDocument.ParseAsync(buffer,cancellationToken:token); }
 public async Task<string> SubmitAsync(string kind,string? value,string? file,CancellationToken token) {
  using var form=new MultipartFormDataContent();
  if(kind=="search") { if(string.IsNullOrWhiteSpace(value)||value.Length>200)throw new ArgumentException("Enter a song name of up to 200 characters."); if(Uri.TryCreate(value,UriKind.Absolute,out _) || value.Contains("://",StringComparison.Ordinal) || Path.IsPathRooted(value))throw new ArgumentException("Enter a song name or a supported HTTPS YouTube link."); form.Add(new StringContent(value.Trim()),"search"); }
  else if(kind=="url") { CheckYoutube(value); form.Add(new StringContent(value!),"url"); }
  else if(kind=="file") { if(string.IsNullOrEmpty(file)||!Extensions.Contains(Path.GetExtension(file),StringComparer.OrdinalIgnoreCase))throw new ArgumentException("Choose a supported audio or video file."); var info=new FileInfo(file); if(!info.Exists || info.Length==0 || info.Length>200L*1024*1024)throw new InvalidDataException("File must be non-empty and at most 200 MB."); var stream=File.OpenRead(file); var content=new StreamContent(stream); content.Headers.ContentType=new MediaTypeHeaderValue("application/octet-stream"); form.Add(content,"file",Path.GetFileName(file)); }
  else throw new ArgumentException("Unsupported transcription input.");
  using var request=new HttpRequestMessage(HttpMethod.Post,"https://api.opennan.com/v1/piano/transcriptions"){Content=form}; request.Headers.Add("Idempotency-Key",Guid.NewGuid().ToString("N")); using var response=await http.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,token); using var doc=await ReadJson(response,token); var root=doc.RootElement; if(!root.TryGetProperty("id",out var id)||id.ValueKind!=JsonValueKind.String)throw new InvalidDataException("Provider did not return a job ID."); return SafeId(id.GetString()!);
 }
 public async Task<TranscriptionStatus> GetStatusAsync(string id,CancellationToken token) { using var response=await http.GetAsync($"https://api.opennan.com/v1/piano/transcriptions/{SafeId(id)}",HttpCompletionOption.ResponseHeadersRead,token); using var doc=await ReadJson(response,token); var root=doc.RootElement; string Get(string key)=>root.TryGetProperty(key,out var p)&&p.ValueKind==JsonValueKind.String?p.GetString()??"":""; var status=Get("status"); if(status is not ("queued" or "running" or "succeeded" or "failed"))throw new InvalidDataException("Unknown transcription status."); double? progress=root.TryGetProperty("progress",out var pr)&&pr.ValueKind==JsonValueKind.Number&&pr.TryGetDouble(out var v)?v:null; string? error=Get("error"); if(root.TryGetProperty("error",out var er)&&er.ValueKind==JsonValueKind.Object&&er.TryGetProperty("message",out var msg))error=msg.GetString(); var source=Get("source_title"); if(string.IsNullOrWhiteSpace(source))source=Get("source_url"); return new(status,Get("stage"),progress,error,source); }
 public Uri DownloadUri(string id)=>new($"https://api.opennan.com/v1/piano/transcriptions/{SafeId(id)}/midi");
}
